# NutriSole G9 Stage H, H2 close-up identity classifier (pre-registered in docs/cv/gauntlet/G9_stageH_prereg.md).
# MobileNetV3-Small (timm mobilenetv3_small_100, ImageNet init), 13 outputs = 12 supported classes + unknown, 224 px.
# Data: (a) Commons H-train (per-file CC/PD, uploaded as private dataset nutrisole-g9h-hset; H-val used for early model selection only;
# H-eval is NOT uploaded), (b) Fruits-360 100x100 (moltean/fruits, CC BY-SA 4.0), folder names mapped to the 12 classes / unknown.
# Leakage guard: Fruits-360 images within pHash Hamming <= 10 of any evaluation hash (H-eval, CU, DEV, M-DEV/M-TEST) are dropped.
# Free Kaggle only (GPU T4 if a free slot, else CPU). No YOLO training.
import glob, json, os, random, subprocess, sys, time
t0 = time.time()
subprocess.run([sys.executable, "-m", "pip", "install", "-q", "imagehash", "onnx"], check=False)
import numpy as np, torch, torch.nn as nn, timm, imagehash
from PIL import Image
BLOB_B64 = ""
W = "/kaggle/working"; random.seed(0); np.random.seed(0); torch.manual_seed(0)
C = ["banana", "apple", "mango", "citrus", "guava", "pomegranate", "lemon_lime", "tomato", "potato", "cucumber", "carrot", "capsicum", "unknown"]
CI = {c: i for i, c in enumerate(C)}
rep = dict(classes=C, notes=[])
# Dataset uploads from the sandbox fail (blob upload unsuccessful, also seen in G9 F/A3), so the Commons H-train / H-val list and the
# evaluation + reference pHash list are embedded below (zlib+base64 JSON) and the Commons 500-px thumbnails are fetched here, politely.
import base64, zlib, urllib.request
BLOB = json.loads(zlib.decompress(base64.b64decode(BLOB_B64)))
meta = BLOB["meta"]; HD = "/tmp/hset"; os.makedirs(f"{HD}/img", exist_ok=True)
evh = [imagehash.hex_to_hash(h) for h in BLOB["eval_hashes"]]
evarr = np.array([np.packbits(h.hash.flatten()) for h in evh], dtype=np.uint8)
def near_eval(img):
    h = np.packbits(imagehash.phash(img).hash.flatten())
    return int(np.unpackbits(evarr ^ h, axis=1).sum(1).min()) <= 10
UA = {"User-Agent": "NutriSoleResearch/1.0 (clydara1@gmail.com)"}; wait = 0.5; got = 0; tdl = time.time()
for k, (lab, sp, url) in meta.items():
    if time.time() - tdl > 1500: break
    for a in range(3):
        try:
            open(f"{HD}/img/{k}.jpg", "wb").write(urllib.request.urlopen(urllib.request.Request(url, headers=UA), timeout=30).read()); got += 1; wait = max(0.5, wait * 0.9); break
        except Exception as e:
            if "429" in str(e): wait = min(20, wait * 2)
            time.sleep(wait)
    time.sleep(wait)
rep["commons_downloaded"] = got; rep["commons_listed"] = len(meta); print("commons", got, len(meta), round(time.time() - tdl), flush=True)
items = {"train": [], "val": []}
for k, (lab, sp, url) in meta.items():
    p = f"{HD}/img/{k}.jpg"
    if os.path.exists(p) and sp in items:
        try: Image.open(p).convert("RGB"); items[sp].append((p, CI[lab], "commons"))
        except Exception: pass
# Fruits-360 mapping (folder name prefix -> class); everything else that is produce -> unknown; ambiguous folders excluded
MAP = [("Apple", "apple"), ("Banana", "banana"), ("Mango", "mango"), ("Orange", "citrus"), ("Mandarine", "citrus"), ("Clementine", "citrus"),
       ("Tangelo", "citrus"), ("Lemon", "lemon_lime"), ("Limes", "lemon_lime"), ("Lime", "lemon_lime"), ("Guava", "guava"), ("Pomegranate", "pomegranate"),
       ("Tomato", "tomato"), ("Potato", "potato"), ("Cucumber", "cucumber"), ("Carrot", "carrot"), ("Pepper Red", "capsicum"), ("Pepper Green", "capsicum"),
       ("Pepper Yellow", "capsicum"), ("Pepper Orange", "capsicum")]
EXCL = ("Grapefruit", "Pomelo", "Pepper", "Cantaloupe", "Melon", "Watermelon", "Ginger", "Zucchini dark")  # citrus-like / ambiguous
roots = sorted(set(os.path.dirname(os.path.dirname(p)) for p in glob.glob("/kaggle/input/**/fruits-360*/**/Training/*/", recursive=True)))
f360 = {}
for r in glob.glob("/kaggle/input/**/Training", recursive=True):
    if "100x100" not in r: continue
    for d in sorted(os.listdir(r)):
        lab = next((c for pre, c in MAP if d.startswith(pre)), None)
        if lab is None and d.startswith(EXCL): continue
        lab = lab or "unknown"; fs = sorted(glob.glob(f"{r}/{d}/*.jpg"))
        f360.setdefault(lab, []).extend(fs[::3])  # every 3rd frame: rotation-sequence frames are near-duplicates
    break
# Fruit Recognition (chrisfilo/fruit-recognition, CC BY 4.0, author-collected lab photos incl. light / pose / partial-occlusion variation)
FRMAP = {"apple": "apple", "banana": "banana", "guava": "guava", "mango": "mango", "orange": "citrus", "pomegranate": "pomegranate", "tomatoes": "tomato", "tomato": "tomato"}
for r in glob.glob("/kaggle/input/**/", recursive=True):
    if "fruit-recognition" not in r.lower() and "fruit_recognition" not in r.lower(): continue
    for d in sorted(os.listdir(r)):
        if not os.path.isdir(f"{r}/{d}") or d.lower() in ("fruit-recognition",): continue
        fs = sorted(f for f in glob.glob(f"{r}/{d}/**/*", recursive=True) if f.lower().endswith((".jpg", ".jpeg", ".png")))
        if not fs: continue
        lab = FRMAP.get(d.lower(), "unknown"); f360.setdefault("fr:" + lab, []).extend(fs)
    break
# Vegetable Image Dataset (misrakahmed/vegetable-image-dataset, CC BY-SA 4.0, farm / market photos), train split only
VGMAP = {"capsicum": "capsicum", "carrot": "carrot", "cucumber": "cucumber", "potato": "potato", "tomato": "tomato"}
for r in glob.glob("/kaggle/input/**/train", recursive=True):
    if "vegetable" not in r.lower(): continue
    for d in sorted(os.listdir(r)):
        fs = sorted(glob.glob(f"{r}/{d}/*.jpg")); lab = VGMAP.get(d.lower(), "unknown"); f360.setdefault("vg:" + lab, []).extend(fs)
    break
print({k: len(v) for k, v in f360.items()}, flush=True)
CAPS = {"f360": 350, "fr": 450, "vg": 450}; UCAPS = {"f360": 1200, "fr": 1200, "vg": 900}
cap = {}; drop = 0; f360n = {}
for key, fs in f360.items():
    src, lab = key.split(":") if ":" in key else ("f360", key)
    cp = (UCAPS if lab == "unknown" else CAPS)[src] * (2 if lab == "lemon_lime" else 1)
    random.shuffle(fs); keep = []
    for f in fs[: int(cp * 1.2)]:
        try: im = Image.open(f).convert("RGB")
        except Exception: continue
        if near_eval(im): drop += 1; continue
        keep.append(f)
        if len(keep) >= cp: break
    f360n[f"{src}:{lab}"] = len(keep); items["train"] += [(f, CI[lab], src) for f in keep]
rep["kaggle_per_source_class"] = f360n; rep["kaggle_dropped_near_eval_or_ref"] = drop
rep["train_per_class"] = {c: sum(1 for _, y, s in items["train"] if y == CI[c]) for c in C}
rep["commons_per_class"] = {c: sum(1 for _, y, s in items["train"] if y == CI[c] and s == "commons") for c in C}
rep["val_per_class"] = {c: sum(1 for _, y, _ in items["val"] if y == CI[c]) for c in C}
print(json.dumps(rep), flush=True)
# Commons near-dup audit vs eval hashes too (belt and braces; the sandbox already dropped them)
cd = 0
for i, (p, y, s) in enumerate(list(items["train"])):
    if s == "commons" and near_eval(Image.open(p).convert("RGB")): cd += 1
rep["commons_train_near_eval"] = cd
dev = "cuda" if torch.cuda.is_available() else "cpu"; rep["device"] = dev
import torchvision.transforms as T
MEAN, STD = (0.485, 0.456, 0.406), (0.229, 0.224, 0.225)
def white_bg_swap(img):  # Fruits-360 studio white background -> random textured background half of the time (domain gap)
    a = np.asarray(img).astype(np.float32)
    if random.random() < 0.5:
        m = (a.min(2) > 235)[..., None]
        bg = np.random.uniform(30, 220, 3)[None, None] + np.random.normal(0, random.uniform(5, 40), a.shape)
        a = np.where(m, bg, a)
    return Image.fromarray(np.clip(a, 0, 255).astype(np.uint8))
tr_tf = T.Compose([T.RandomResizedCrop(224, scale=(0.35, 1.0), ratio=(0.7, 1.4)), T.RandomHorizontalFlip(), T.RandomRotation(25),
                   T.ColorJitter(0.35, 0.35, 0.25, 0.03), T.RandomGrayscale(0.02), T.ToTensor(), T.Normalize(MEAN, STD)])
va_tf = T.Compose([T.Resize(256), T.CenterCrop(224), T.ToTensor(), T.Normalize(MEAN, STD)])
class DS(torch.utils.data.Dataset):
    def __init__(s, it, tf): s.it, s.tf = it, tf
    def __len__(s): return len(s.it)
    def __getitem__(s, i):
        p, y, src = s.it[i]; im = Image.open(p).convert("RGB")
        if src == "f360" and s.tf is tr_tf: im = white_bg_swap(im.resize((160, 160)))
        elif src == "fr" and s.tf is tr_tf and random.random() < 0.5: im = white_bg_swap(im)
        return s.tf(im), y
ys = np.array([y for _, y, _ in items["train"]]); cw = 1.0 / np.bincount(ys, minlength=len(C)).clip(1)
sampler = torch.utils.data.WeightedRandomSampler(cw[ys], num_samples=len(ys), replacement=True)
tl = torch.utils.data.DataLoader(DS(items["train"], tr_tf), batch_size=64, sampler=sampler, num_workers=4, drop_last=True)
vl = torch.utils.data.DataLoader(DS(items["val"], va_tf), batch_size=128, num_workers=4)
model = timm.create_model("mobilenetv3_small_100", pretrained=True, num_classes=len(C)).to(dev)
EP = 14; opt = torch.optim.AdamW(model.parameters(), lr=1.5e-3, weight_decay=0.02)
sch = torch.optim.lr_scheduler.OneCycleLR(opt, max_lr=1.5e-3, total_steps=EP * len(tl), pct_start=0.15)
crit = nn.CrossEntropyLoss(label_smoothing=0.1); best = (-1, None); hist = []
def evaluate():
    model.eval(); P, Y = [], []
    with torch.no_grad():
        for x, y in vl: P.append(torch.softmax(model(x.to(dev)), 1).cpu().numpy()); Y.append(y.numpy())
    P, Y = np.concatenate(P), np.concatenate(Y); pr = P.argmax(1)
    sup = Y != CI["unknown"]
    return dict(acc=float((pr == Y).mean()), sup_acc=float((pr[sup] == Y[sup]).mean()), unk_recall=float((pr[~sup] == CI["unknown"]).mean()) if (~sup).any() else None,
                bal=float(np.mean([(pr[Y == c] == c).mean() for c in range(len(C)) if (Y == c).any()])))
for ep in range(EP):
    model.train(); tl_sum = 0
    for x, y in tl:
        x, y = x.to(dev), y.to(dev); opt.zero_grad(); loss = crit(model(x), y); loss.backward(); opt.step(); sch.step(); tl_sum += loss.item()
    m = evaluate(); m.update(ep=ep, loss=tl_sum / len(tl), t=round(time.time() - t0)); hist.append(m); print(m, flush=True)
    if m["bal"] > best[0]: best = (m["bal"], {k: v.detach().clone() for k, v in model.state_dict().items()})
model.load_state_dict(best[1]); model.eval().cpu()
class Wrap(nn.Module):
    def __init__(s, m): super().__init__(); s.m = m
    def forward(s, x): return torch.softmax(s.m(x), 1)
torch.onnx.export(Wrap(model), torch.zeros(1, 3, 224, 224), f"{W}/h2_mnv3s.onnx", input_names=["images"], output_names=["probs"], opset_version=17,
                  dynamic_axes={"images": {0: "n"}, "probs": {0: "n"}})
rep.update(history=hist, best_val_bal=best[0], minutes=round((time.time() - t0) / 60, 1), input="RGB 224 (resize short side 256 -> centre crop 224 at eval), ImageNet mean/std")
json.dump(rep, open(f"{W}/h2_report.json", "w"), indent=1); print("DONE", rep["minutes"], flush=True)
